script.text:
			/* <flatten type="Javascript"> */
function load$GridReport$(g) {
	g.add_commandEvent(on$GridReport$ExecuteCommand);
	g.add_onRender(on$GridReport$Render);
	g.add_onResponseComplete(on$GridReport$ResponseComplete);
	g._$k = [];
	g._$i = g._getColumnOrder('stt_rec');
	g._$t = g._getColumnOrder('tag');
}
function scatter$GridReport$(g) {
	fill$Grid(g, true);
	if (g._rowCount > 0) {
		g._activeRow = g._rowCount;
		g._activeColumn = g._$t;
		g._activeCell = g._getItem(g._activeRow, g._activeColumn);
	}
}
function dispose$GridReport$(g) {
	g._$k = g._$i = g._$t = null;
	try {g.remove_commandEvent(on$GridReport$ExecuteCommand);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridReport$ResponseComplete);} catch (ex) {}
	try {g.remove_onRender(on$GridReport$Render);} catch (ex) {}
}
function on$GridReport$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, id = g.get_id(), type = 0;
	switch (action) {
		case 'Truncate':
			if (!isCheck$Grid(g)) break;
			var msg = (g._language == 'v' ? 'Hệ thống sẽ <span class="Highlight">xóa bản ghi đang được chọn</span>, bạn có chắc chắn thực hiện không?' : 'Are you sure you want to <span class="Highlight">delete the selected records</span>?');
			$message.show(msg, 0, String.format('request$Delete($find(\'{0}\'), {1});', id), String.format('$find(\'{0}\')._focusWhenTabChanged();', id));
			break;
		default:
			break;
	}
}
function on$GridReport$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, f = g.get_element().parentForm;
	switch (context) {
		default:
			break;
	}
}
function on$GridReport$Render(sender, eventArgs) {
	var g = eventArgs.grid;
	if (g._hiddenFields) {
		var a = g._hiddenFields, h = '';
		for (var i = 0; i < a.length; i++) {
			setGridHiddenFields(g, a[i].Fields, a[i].Value);
			if (a[i].Value) h += (h == '' ? '' : ',') + a[i].Fields;
		}
		g._externalHiddenFields = h;
	}
}
function setGridHiddenFields(g, c, v) {
	var a = c.split(',');
	for (var i = 0; i < a.length; i++) {
		var l = g._getColumnOrder($func.trim(a[i]));
		if (l != -1) g._setColumnVisible(l, !v);
	}
}
function beforeDrillDown(g) {g._args.cancelEvent = !($func.trim(g._getItemValue(g._activeRow, g._activeColumn)));}
function formatDateView(c) {return String.format('{0}/{1}/{2}', c.substring(6, 8), c.substring(4, 6), c.substring(0, 4));}

function request$Delete(g) {g.showForm('DeleteMultipeVoucherProcess');}
function genHash(o) {
	var f = o.parentForm, p = $func.trim(MD5(o.value));
	f.getItem('chkpass').value = CRC32($func.trim(f._key).substr(0, 8) + p.substr(1, p.length - 2));
}
function checkFieldEntry(f, o, force) {
	if (force) o = f.getItem(o);
	var v = force ? o.value : o.oldValue;
	if (f._checked && !v) {
		f._checked = false;
		$func.hideWait(f.get_id());
		$message.show(String.format($df.getResources(f._language, 'Message.RequiredField'), o.field.Label), String.format('revertPassword(\'{0}\', \'\', true); $find(\'{0}\').focus(\'{1}\');', f.get_id(), o.field.Name));
	}
}
function revertPassword(f, name, force) {
	if (force) f = $find(f);
	var o = f.getItem('cpass');
	if (o.oldValue) o.value = o.oldValue;
}
function busy$Page(f, type) {
	var id = f._id;
	f._busy = type;
	if (type) $func.showWait(id);
		else $func.hideWait(id);
	$func.enableButtons(!type);
}
function refresh$Page(g) {
	g._$k = [];
	g.goToPage(-1);
}
/* </flatten> */
			&ScriptTagReport;
